def trans8(g):
 from collections import deque
 out=[r[:] for r in g]; seeds=[(i,j) for i,r in enumerate(g) for j,x in enumerate(r) if x not in (0,3)]; color=g[seeds[0][0]][seeds[0][1]]; q=deque(seeds); seen=set(seeds); h=len(g);w=len(g[0])
 while q:
  i,j=q.popleft()
  for di in (-1,0,1):
   for dj in (-1,0,1):
    ni,nj=i+di,j+dj
    if (di or dj) and 0<=ni<h and 0<=nj<w and (ni,nj) not in seen and g[ni][nj]==0:
     seen.add((ni,nj));q.append((ni,nj));out[ni][nj]=color
 return out
